/**
 * @jest-environment jsdom
 *
 * Tests for dataManager component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Shared state management using module-level cache
 * - Uses wire adapters for work items and templates
 * - Exports clearCache() for test isolation
 * - Broadcasts data changes to all instances
 */
import { createElement } from 'lwc';
import DataManager, { clearCache } from 'c/dataManager';
import getWorkItemsForProject from '@salesforce/apex/WorkItemController.getWorkItemsForProject';
import getWorkItemWithChildren from '@salesforce/apex/WorkItemController.getWorkItemWithChildren';
import getWorkItemTemplates from '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemsForProject',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemWithChildren',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.moveWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock getRecord wire
jest.mock('lightning/uiRecordApi', () => ({
    getRecord: jest.fn(),
    getFieldValue: jest.fn()
}), { virtual: true });

// Mock schema field
jest.mock(
    '@salesforce/schema/Work_Item__c.Project__c',
    () => ({ fieldApiName: 'Project__c', objectApiName: 'Work_Item__c' }),
    { virtual: true }
);

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-data-manager', () => {
    // Clean up DOM, mocks, and module cache after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        clearCache(); // Clear module-level cache for test isolation
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-data-manager', {
            is: DataManager
        });
        Object.assign(element, {
            recordId: 'proj-001',
            objectApiName: 'cgpm__Project__c',
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('accepts recordId property', () => {
            const element = createComponent({ recordId: 'proj-002' });
            expect(element.recordId).toBe('proj-002');
        });

        it('accepts objectApiName property', () => {
            const element = createComponent({ objectApiName: 'cgpm__Work_Item__c' });
            expect(element.objectApiName).toBe('cgpm__Work_Item__c');
        });

        it('accepts hierarchyDepth property with default of 3', () => {
            const element = createComponent();
            expect(element.hierarchyDepth).toBe(3);
        });
    });

    describe('@api methods', () => {
        it('has notifyDataLoaded method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.notifyDataLoaded).toBe('function');
        });

        it('notifyDataLoaded dispatches workitemsload event', async () => {
            const element = createComponent();
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('workitemsload', handler);

            element.notifyDataLoaded({ workItems: [], statusOptions: [] });

            expect(handler).toHaveBeenCalledTimes(1);
        });

        it('has refresh method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.refresh).toBe('function');
        });

        it('has moveWorkItem method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.moveWorkItem).toBe('function');
        });
    });

    describe('context detection', () => {
        it('detects project page from objectApiName', async () => {
            const element = createComponent({
                objectApiName: 'cgpm__Project__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });

        it('detects work item page from objectApiName', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });
    });

    describe('wire adapter - Project context', () => {
        it('handles work items wire data on project page', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('workitemsload', handler);

            // Emit data
            getWorkItemsForProject.emit({
                workItems: [
                    { id: 'wi-001', name: 'Task 1', children: [] }
                ],
                statusOptions: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
        });
    });

    describe('wire adapter - Work Item context', () => {
        it('processes work item wire data on work item page', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            // Emit data - the component will process it (broadcasts use module-level cache)
            // Note: The broadcast mechanism uses effectiveProjectId which requires
            // the projectId to be resolved via getRecord wire. For unit testing,
            // we verify the component processes the wire data without errors.
            getWorkItemWithChildren.emit({
                id: 'wi-001',
                name: 'Parent Task',
                children: [
                    { id: 'wi-002', name: 'Child Task', children: [] }
                ]
            });
            await flushPromises();

            // Component should process wire data without errors
            expect(element).toBeDefined();
        });

        it('handles wire error gracefully', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            // Emit error
            getWorkItemWithChildren.error({ message: 'Work item not found' });
            await flushPromises();

            // Component should handle error without crashing
            expect(element).toBeDefined();
        });
    });

    describe('templates wire adapter', () => {
        it('dispatches templatesload event when templates loaded', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('templatesload', handler);

            // Emit templates
            getWorkItemTemplates.emit([
                { Id: 'template-001', Name: 'Task' }
            ]);
            await flushPromises();

            expect(handler).toHaveBeenCalled();
        });
    });

    describe('module-level cache', () => {
        it('clearCache function is exported', () => {
            expect(typeof clearCache).toBe('function');
        });

        it('clearCache can be called without errors', () => {
            expect(() => clearCache()).not.toThrow();
        });
    });
});

