/**
 * @description Controller class for Work Item Lightning Web Components
 * Provides @AuraEnabled methods for querying and manipulating Work Items
 *
 * @group Controllers
 *
 * @date 2025-10-06
 */
public with sharing class WorkItemController {
    /**
     * @description Wrapper class for Project data with Work Items
     */
    public class ProjectDataWrapper {
        @AuraEnabled
        public Id projectId { get; set; }
        @AuraEnabled
        public Date projectStartDate { get; set; }
        @AuraEnabled
        public Date projectDueDate { get; set; }
        @AuraEnabled
        public List<WorkItemWrapper> workItems { get; set; }
        @AuraEnabled
        public List<PicklistOption> statusOptions { get; set; }

        private Set<String> statusNames { get; set; }

        public ProjectDataWrapper(Id projectId, Date startDate, Date dueDate, List<WorkItemWrapper> items) {
            this.projectId = projectId;
            this.projectStartDate = startDate;
            this.projectDueDate = dueDate;
            this.workItems = items;

            this.statusNames = new Set<String>();
            this.getStatusOptions(items);

            this.statusOptions = new List<PicklistOption>{ new PicklistOption('All Statuses', '') };
            for (String statusName : statusNames) {
                this.statusOptions.add(new PicklistOption(statusName, statusName));
            }
        }

        private void getStatusOptions(List<WorkItemWrapper> items) {
            for (WorkItemWrapper item : items) {
                if (item.workflow != null) {
                    for (StatusOption option : item.workflow) {
                        statusNames.add(option.name);
                    }
                }

                if (item.children != null) {
                    this.getStatusOptions(item.children);
                }
            }
        }
    }

    /**
     * @description Wrapper class for Work Item Assignments
     */
    public class WorkItemAssignmentWrapper {
        @AuraEnabled
        public Id id { get; set; }
        @AuraEnabled
        public String resourceName { get; set; }
        @AuraEnabled
        public String role { get; set; }
        @AuraEnabled
        public Boolean isPrimary { get; set; }
        @AuraEnabled
        public Id projectRoleId { get; set; }
        @AuraEnabled
        public String projectRoleName { get; set; }
    }

    /**
     * @description Wrapper class for Work Items with hierarchical children
     */
    public class WorkItemWrapper {
        @AuraEnabled
        public Id id { get; set; }
        @AuraEnabled
        public String name { get; set; }
        @AuraEnabled
        public String status { get; set; }
        @AuraEnabled
        public Date startDate { get; set; }
        @AuraEnabled
        public Date dueDate { get; set; }
        @AuraEnabled
        public Decimal estimatedHours { get; set; }
        @AuraEnabled
        public Decimal actualHours { get; set; }
        @AuraEnabled
        public String description { get; set; }
        @AuraEnabled
        public String nextSteps { get; set; }
        @AuraEnabled
        public Id projectId { get; set; }
        @AuraEnabled
        public Id parentWorkItemId { get; set; }
